mapper.sql:
FROM vi_aftersale_case c
JOIN vi_order o ON o.id = c.order_id
WHERE 1 = 1



            AND o.dept_id IN

                #{d}



            AND 1 = 0




    AND o.id = #{orderId}


    AND o.owner_account_id = #{ownerId}


    AND (LOCATE(#{query.keyword}, o.order_no) > 0
        OR LOCATE(#{query.keyword}, c.case_no) > 0)


    AND c.case_status = #{query.status}


    AND c.kind = #{query.kind}


    AND c.return_state = #{query.returnState}


    AND c.refund_state = #{query.refundState}

mapper.select:
SELECT c.*

ORDER BY c.created_at DESC, c.id DESC
LIMIT #{query.pageSize} OFFSET #{offset}

SELECT id
FROM vi_order
WHERE order_no = #{no}

SELECT DISTINCT sys_user_id
FROM vi_employee_binding
WHERE account_id = #{accountId}

SELECT phonenumber
FROM sys_user
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM (
    SELECT user_id
    FROM vi_aftersale_participant_user
    WHERE case_id = #{caseId}
        AND user_id = #{userId}
    UNION
    SELECT applicant_id
    FROM vi_aftersale_case
    WHERE id = #{caseId}
        AND applicant_type = 'SYS_USER'
        AND applicant_id = #{userId}
    UNION
    SELECT user_id
    FROM vi_aftersale_note
    WHERE case_id = #{caseId}
        AND user_id = #{userId}
) contributors

SELECT COALESCE(NULLIF(nickname, ''), '车主')
FROM vi_account
WHERE id = #{accountId}

