mapper.delete:
DELETE FROM vi_driver_occupancy
WHERE driver_id = #{driverId}
    AND order_id = #{orderId}
    AND holder_id = #{holderId}
    AND holder_type = #{holderType}

mapper.update:
UPDATE vi_quota_slot
SET


            held_quota = held_quota - #{quantity},


            confirmed_quota = confirmed_quota - #{quantity},


    version = version + 1,
    updated_at = UTC_TIMESTAMP(3)
WHERE id = #{slotId}
    AND

        held_quota >= #{quantity}
        confirmed_quota >= #{quantity}
